import zipfile, xml.etree.ElementTree as ET, statistics
ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
RID='{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'

def get_geom(el):
    # try common transform paths for shapes/pictures/charts
    candidates=[
        './/p:spPr/a:xfrm',
        './/p:xfrm',
        './/a:xfrm'
    ]
    for xp in candidates:
        xfrm=el.find(xp, ns)
        if xfrm is not None:
            off=xfrm.find('a:off', ns) or xfrm.find('p:off', ns)
            ext=xfrm.find('a:ext', ns) or xfrm.find('p:ext', ns)
            if off is not None and ext is not None:
                try:
                    return int(off.attrib['x']), int(off.attrib['y']), int(ext.attrib['cx']), int(ext.attrib['cy'])
                except Exception:
                    pass
    return 0,0,0,0

def parse_ppt(path):
    z=zipfile.ZipFile(path)
    pres=ET.fromstring(z.read('ppt/presentation.xml'))
    sldSz=pres.find('p:sldSz', ns)
    W,H=int(sldSz.attrib['cx']), int(sldSz.attrib['cy'])
    pres_rels=ET.fromstring(z.read('ppt/_rels/presentation.xml.rels'))
    relmap={rel.attrib['Id']:rel.attrib['Target'] for rel in pres_rels}
    slide_paths=[]
    for sldId in pres.findall('p:sldIdLst/p:sldId', ns):
        slide_paths.append('ppt/'+relmap[sldId.attrib[RID]].lstrip('/'))
    slides=[]
    for spath in slide_paths:
        root=ET.fromstring(z.read(spath))
        spTree=root.find('p:cSld/p:spTree', ns)
        texts=[]; pic_count=0; gfx_count=0; pic_area=0; text_area=0
        if spTree is None:
            slides.append({'texts':[],'pic_count':0,'gfx_count':0,'pic_ratio':0,'text_ratio':0})
            continue
        for child in list(spTree):
            tag=child.tag.split('}')[-1]
            x,y,cx,cy=get_geom(child)
            area=cx*cy
            if tag=='pic':
                pic_count+=1; pic_area+=area
            elif tag=='graphicFrame':
                gfx_count+=1; pic_area+=area
            elif tag=='sp':
                t=''.join([(n.text or '') for n in child.findall('.//a:t', ns)]).strip()
                if t:
